                actionText = `使用 ${data.name}`;
                break;
            case 'travel':
                actionText = `玩家 前往 ${data.location}，相距${data.distance}公里`;
                break;
            case 'communicate':
                actionText = `对${context.charName}说：“${data}”`;
                break;
            case 'gift':
                actionText = `将[${data.name}]赠送给${context.charName}`;
                break;
            case 'spar':
                actionText = `向${context.charName}发起切磋请求`;
                break;
            case 'accompany':
