                break;
            case 'refining':
                actionText = `玩家使用[${data.map(i => i.name).join(', ')}]开始炼器`;
                break;
        }

        if(type === 'travel') {
                actionQueue = actionQueue.filter(a => a.type !== 'travel');
        }

        actionQueue.push({ type, text: actionText, data: data, context: context });

        renderActionQueue();

        if(type === 'use') closeItemDetail();
