tempEl.innerHTML = log.content.replace(/<br\s*\/?>/gi, '\n');
return tempEl.value;
}).join(separator);

const dataBlob = new Blob([textContent], {type: "text/plain;charset=utf-8"});
const url = URL.createObjectURL(dataBlob);
