                    showCustomAlert("自定义形象已设置！");
                }
            } else if (type === 'npc' && currentEditingNpcId) {
                const archive = await db.archives.get(currentArchiveName);
                if (!archive.data.state.npcAvatars) {
                    archive.data.state.npcAvatars = {};
