async function reUploadWorkshopItem(objectId) {
try {
const work = await new AV.Query('PresetWorkshop').get(objectId);
const category = work.get('category');

const config = categoryConfig[category];

let dataToUpload;
if (category === 'preset') {
dataToUpload = await getPresetDataForExport();
} else {
dataToUpload = await dbGet(config.dbKey) || [];
}

const dataLength = Array.isArray(dataToUpload) ? dataToUpload.length : Object.keys(dataToUpload).length;
if (dataLength === 0) {
await showCustomAlert(`你本地没有“${config.name}”数据，无法更新。`);
return;
}

const name = await showCustomPrompt('请输入新的名称:', work.get('name'));
if (!name) return;
const description = await showCustomPrompt('请输入新的描述:', work.get('description'));
if (description === null) return;
const tagsStr = await showCustomPrompt('请输入新的标签 (用逗号或空格分隔):', (work.get('tags') || []).join(', '));
if (tagsStr === null) return;

const tags = tagsStr.split(/[\s,，]+/).filter(Boolean);
const dataString = JSON.stringify(dataToUpload);

work.set('name', name);
work.set('description', description);
work.set('tags', tags);
work.set('presetData', dataString);
work.set('version', '8.5');

await work.save();
await showCustomAlert('作品更新成功！');
await openWorkshopManagement(); // Refresh the list

} catch (error) {
console.error("更新作品失败:", error);
await showCustomAlert(`更新失败: ${error.message}`);
}
}

