    function sanitizeHTML(htmlString) {
        let sanitized = String(htmlString).replace(/<script\b[^>]*>([\s\S]*?)<\/script>/gi, '');
        sanitized = sanitized.replace(/\s(on\w+)=["'][^"']*["']/gi, '');
        return sanitized;
    }

    function enforceRenderLimit() {
        const limit = regexConfig.renderLimit || 100;
        const messages = mainContentArea.querySelectorAll('.log-entry');
        if (messages.length > limit) {
            const toRemove = messages.length - limit;
            for(let i = 0; i < toRemove; i++) {
                messages[i].remove();
            }
        }
    }

    function processAndRenderHtmlBlocks(rawContent) {
const regex = /```html\n([\s\S]*?)\n```/g;
const parts = rawContent.split(regex);

const processedParts = parts.map((part, index) => {

if (index % 2 === 0) {
return sanitizeHTML(part);
}

else {

const htmlContent = part;

const encodedContent = encodeURIComponent(htmlContent);

return `<iframe class="html-render-frame" src="data:text/html;charset=utf-8,${encodedContent}" sandbox="allow-scripts allow-same-origin"></iframe>`;
}
});

return processedParts.join('');
}

    function createLogEntryElement(logData, type) {
const isSummary = (typeof logData !== 'string' && (logData.content.startsWith('[天道总结:') || logData.content.includes('<h4>天道初启</h4>')));
const logEntry = document.createElement('div');
logEntry.classList.add('log-entry', type);
