if (workshopSortBy === 'random') {
const maxSkip = Math.max(0, count - WORKSHOP_PAGE_SIZE);
const randomSkip = Math.floor(Math.random() * (maxSkip + 1));
query.skip(randomSkip);
} else {
query.descending(workshopSortBy);
query.skip((workshopCurrentPage - 1) * WORKSHOP_PAGE_SIZE);
}

query.limit(WORKSHOP_PAGE_SIZE);

const presets = await query.find();

renderWorkshopPresets(presets);
renderWorkshopPagination(count);

} catch (error) {
console.error("获取工坊预设失败:", error);
listEl.innerHTML = `<p style="text-align:center; color: #e57373;">获取失败: ${error.message}</p>`;
